const p = msg.payload || {};
if ((p.cim_api_key || "").length === 0) {
    node.error("missing CIM api key in msg.payload", msg);
    return null;
}
return msg;

// Stash form input for the post-HTTP step
msg.config_variables = msg.payload;

// Decode JWT payload (middle segment, base64url-encoded JSON).
// JWT carries `iss` (issuer URL, the CIM tenant root) and `instanceId`.
try {
    const parts = (msg.payload.cim_api_key || "").split(".");
    if (parts.length < 2) throw new Error("not a JWT");
    const b64 = parts[1].replace(/-/g, "+").replace(/_/g, "/");
    const padded = b64 + "=".repeat((4 - b64.length % 4) % 4);
    const decoded = JSON.parse(Buffer.from(padded, "base64").toString("utf8"));
    if (!decoded.iss || decoded.instanceId === undefined) {
        throw new Error("missing iss or instanceId");
    }
    msg.config_variables.cim_iss = decoded.iss;
    msg.config_variables.cim_instance_id = decoded.instanceId;
    msg.config_variables.cim_base_url = decoded.iss.replace(/\/+$/, "") + "/_webservices/case_management/rest/1.0";
} catch (err) {
    node.error("Invalid CIM api key (JWT decode failed): " + err.message, msg);
    return null;
}

msg.headers = { "Authorization": "Bearer " + msg.config_variables.cim_api_key };
msg.url = msg.config_variables.cim_base_url + "/cases?limit=1";
return msg;

// Connectivity probe \u2014 the API key is valid if /cases returns a cases array.
if (!msg.payload || !Array.isArray(msg.payload.cases)) {
    node.error("CIM /cases endpoint did not return a cases array \u2014 invalid api key or instance unreachable", msg);
    return null;
}
return msg;

const v = msg.config_variables;
const sender_override = (v.cim_sender_name || "").trim() || null;
const instance_id = v.cim_instance_id;

msg.payload = {
    // Standard client contract fields
    client_system: "cim",
    api_key:    v.cim_api_key,
    identifier: String(instance_id),
    name:       sender_override || ("CIM " + instance_id),
    timestamp:  Date.now(),
    client_specific: {
        // CIM-specific fields
        api_key:     v.cim_api_key,
        base_url:    v.cim_base_url,
        iss:         v.cim_iss,
        instance_id: instance_id,
        sender_override: sender_override
    }
};
return msg;

const config = msg.payload;

msg.topic = config.client_system;

if (config.identifier &&
    config.client_specific.api_key &&
    config.client_specific.base_url &&
    config.client_specific.instance_id !== undefined) {
    return msg;
}
node.error("CIM config not correctly configured", config);
return null;
